(function(){
'use strict';
const M = GF.math;
const W = 960, H = 540;
const C = { teal:'#3ff2c8', gold:'#ffd977', deep:'#0d2b33', dark:'#060d14', dim:'#1b4a52' };

const game = new GF.Game({
  id: 'lumen-current',
  title: 'Lumen Current: Signal Garden',
  width: W, height: H,
  palette: ['#3ff2c8', '#ffd977', '#0d2b33', '#060d14'],
  background: '#060d14',
  seed: (typeof window.__GF_VERIFIER_SEED__ === 'number') ? window.__GF_VERIFIER_SEED__ : 1337
});

const NODE_RADIUS = 140;
const NODES = [
  { x: 700, y: 270 },
  { x: 250, y: 505 },
  { x: 480, y: 160 }
];
const HAZARD_STEPS = [1.0, 1.35, 1.7];

const play = {
  init() {
    // static background layers, built once
    this.bgGrad = null;
    this.veins = [];
    const rng = M.makeRng(4242);
    for (let i = 0; i < 46; i++) {
      const x = rng() * W, y = rng() * H;
      const a = rng() * M.TAU;
      const len = 40 + rng() * 130;
      this.veins.push({ x1: x, y1: y, x2: x + Math.cos(a) * len, y2: y + Math.sin(a) * len, w: 1 + rng() * 2 });
    }
    this.motes = [];
    for (let i = 0; i < 70; i++) this.motes.push({ x: rng() * W, y: rng() * H, s: 6 + rng() * 22, r: 0.8 + rng() * 1.8, ph: rng() * M.TAU });
    // chain path spawn -> nodes (vine circuitry)
    this.chain = [
      { x1: 480, y1: 270, x2: NODES[0].x, y2: NODES[0].y, lit: 0 },
      { x1: NODES[0].x, y1: NODES[0].y, x2: NODES[1].x, y2: NODES[1].y, lit: 0 },
      { x1: NODES[1].x, y1: NODES[1].y, x2: NODES[2].x, y2: NODES[2].y, lit: 0 }
    ];
    this.trail = new Float32Array(60); // x,y pairs ring buffer
    this.trailIdx = 0;
    this.bgGrad = null;
  },

  reset() {
    if (this.runCount === undefined) this.runCount = 0;
    if (this.runCount > 0) {
      game.event('run_restarted', { before: this.runCount, after: this.runCount + 1 });
    }
    this.runCount++;
    this.stability = 100;
    this.nodesActivated = 0;
    this.hazardSpeed = HAZARD_STEPS[0];
    this.pulses = [];
    this.spores = [];
    this.pulseTimer = 1.2;
    this.sporeTimer = 0.5;
    this.moveEmitT = 0;
    this.lastEmitX = 480;
    this.warned25 = false;
    this.musicT = 0;
    this.player = { x: 480, y: 270, vx: 0, vy: 0 };
    for (const n of NODES) { n.active = false; n.pulse = 0; n.hint = 0; }
    for (const c of this.chain) c.lit = 0;
    for (let i = 0; i < this.trail.length; i += 2) { this.trail[i] = 480; this.trail[i + 1] = 270; }
  },

  activateNode(i) {
    const n = NODES[i];
    if (n.active || game.state !== 'playing') return;
    n.active = true;
    n.pulse = 1;
    this.nodesActivated = i + 1;
    const before = this.hazardSpeed;
    this.hazardSpeed = HAZARD_STEPS[this.nodesActivated] || HAZARD_STEPS[2];
    game.addScore(100);
    this.stability = M.clamp(this.stability + 35, 0, 100);
    game.hitStop(0.06);
    game.shake(8, 0.3);
    game.flash('#bfffe9', 0.4);
    game.burst(n.x, n.y, { count: 46, speed: 260, size: 4, life: 0.9, colors: [C.teal, C.gold, '#eafff8'], gravity: 0 });
    game.event('pressure_escalated', { before: before, after: this.hazardSpeed, node: this.nodesActivated });
    GF.Sfx.melody([[523, 0.09], [659, 0.09], [784, 0.09], [1046, 0.22]], { type: 'triangle', vol: 0.4 });
    GF.Sfx.noise({ dur: 0.35, vol: 0.18, freq: 900 });
    // vine circuitry races toward next node
    if (i < 3) {
      const seg = this.chain[i];
      game.tween(seg, { lit: 1 }, 0.9, 'outQuad');
    }
    if (this.nodesActivated >= 3) {
      game.burst(480, 270, { count: 80, speed: 340, size: 5, life: 1.2, colors: [C.teal, C.gold, '#ffffff'], gravity: 0 });
      game.event('state_reached', { state: 'success', nodesActivated: 3 });
      game.win({ message: 'THE GARDEN AWAKENS' });
    }
  },

  damage(amount, x, y) {
    if (game.state !== 'playing') return;
    this.stability -= amount;
    game.shake(5, 0.25);
    game.hitStop(0.04);
    game.burst(x, y, { count: 12, speed: 150, size: 3, life: 0.5, colors: [C.gold, '#ff9a6b'], gravity: 60 });
    GF.Sfx.beep({ freq: 220, to: 90, dur: 0.18, type: 'sawtooth', vol: 0.28 });
    if (this.stability <= 25 && !this.warned25) {
      this.warned25 = true;
      game.flash('#ffb066', 0.3);
      GF.Sfx.beep({ freq: 160, to: 120, dur: 0.4, type: 'triangle', vol: 0.3 });
    }
    if (this.stability <= 0) {
      this.stability = 0;
      game.event('state_reached', { state: 'failure', stability: 0 });
      game.gameOver({ message: 'THE CURRENT GUTTERS OUT' });
    }
  },

  update(dt) {
    const p = this.player;
    // ---- movement (MH-01) ----
    const k = game.input.keys;
    let ax = 0, ay = 0;
    if (k['ArrowLeft'] || k['KeyA']) ax -= 1;
    if (k['ArrowRight'] || k['KeyD']) ax += 1;
    if (k['ArrowUp'] || k['KeyW']) ay = -1; else ay = 0;
    if (k['ArrowDown'] || k['KeyS']) ay += 1;
    const al = Math.hypot(ax, ay) || 1;
    p.vx += (ax / al) * 1500 * dt;
    p.vy += (ay / al) * 1500 * dt;
    const damp = Math.pow(0.12, dt);
    p.vx *= damp; p.vy *= damp;
    const sp = Math.hypot(p.vx, p.vy);
    const maxSp = 285;
    if (sp > maxSp) { p.vx = p.vx / sp * maxSp; p.vy = p.vy / sp * maxSp; }
    const ox = p.x;
    p.x = M.clamp(p.x + p.vx * dt, 26, W - 26);
    p.y = M.clamp(p.y + p.vy * dt, 40, H - 30);
    // trail ring buffer
    this.trailIdx = (this.trailIdx + 2) % this.trail.length;
    this.trail[this.trailIdx] = p.x;
    this.trail[this.trailIdx + 1] = p.y;
    // evidence: player_moved (PR-MH-01)
    this.moveEmitT -= dt;
    if (this.moveEmitT <= 0 && Math.abs(p.x - this.lastEmitX) > 3) {
      game.event('player_moved', { before: Math.round(this.lastEmitX), after: Math.round(p.x), playerX: Math.round(p.x) });
      this.lastEmitX = p.x;
      this.moveEmitT = 0.35;
    }

    // ---- channel action (Space/Enter/click) (MH-02, NG-03) ----
    const act = game.input.pressed('Space') || game.input.pressed('Enter') || game.input.pointer.clicked;
    let inRadius = -1;
    for (let i = 0; i < 3; i++) {
      const n = NODES[i];
      const d = M.dist(p.x, p.y, n.x, n.y);
      if (!n.active && d < NODE_RADIUS) inRadius = i;
      if (n.pulse > 0) n.pulse = Math.max(0, n.pulse - dt * 1.4);
    }
    if (act && inRadius >= 0) this.activateNode(inRadius);

    // ---- stability passive drain, escalates with nodes + time (MH-04, MH-07) ----
    this.stability -= (1.2 + 0.4 * this.nodesActivated + game.time * 0.02) * dt;
    if (this.stability <= 0 && game.state === 'playing') this.damage(0.01, p.x, p.y);

    // ---- storm pulses (hazards) ----
    this.pulseTimer -= dt;
    if (this.pulseTimer <= 0) {
      const interval = M.clamp(2.5 - this.nodesActivated * 0.45 - game.time * 0.012, 0.9, 3);
      this.pulseTimer = interval;
      const rng = game.rng;
      this.pulses.push({ x: 60 + rng() * (W - 120), y: 60 + rng() * (H - 120), r: 8, maxR: 200 + rng() * 140, hit: false });
    }
    for (let i = this.pulses.length - 1; i >= 0; i--) {
      const pu = this.pulses[i];
      pu.r += 95 * this.hazardSpeed * dt;
      const d = M.dist(p.x, p.y, pu.x, pu.y);
      if (!pu.hit && Math.abs(d - pu.r) < 16) {
        pu.hit = true;
        this.damage(10, p.x, p.y);
      }
      if (pu.r > pu.maxR) this.pulses.splice(i, 1);
    }
    // ---- spore orbs ----
    this.sporeTimer -= dt;
    const targetSpores = 3 + this.nodesActivated * 3;
    if (this.sporeTimer <= 0 && this.spores.length < targetSpores) {
      this.sporeTimer = 0.8;
      const rng = game.rng;
      const edge = (rng() * 4) | 0;
      let sx = 0, sy = 0;
      if (edge === 0) { sx = rng() * W; sy = -20; }
      else if (edge === 1) { sx = W + 20; sy = rng() * H; }
      else if (edge === 2) { sx = rng() * W; sy = H + 20; }
      else { sx = -20; sy = rng() * H; }
      const a = Math.atan2(270 - sy, 480 - sx) + (rng() - 0.5) * 1.2;
      this.spores.push({ x: sx, y: sy, vx: Math.cos(a) * 70, vy: Math.sin(a) * 70, r: 9 + rng() * 6, cd: 0, ph: rng() * M.TAU });
    }
    for (let i = this.spores.length - 1; i >= 0; i--) {
      const s = this.spores[i];
      s.x += s.vx * this.hazardSpeed * dt;
      s.y += s.vy * this.hazardSpeed * dt;
      s.ph += dt * 3;
      if (s.cd > 0) s.cd -= dt;
      if (s.x < -60 || s.x > W + 60 || s.y < -60 || s.y > H + 60) { this.spores.splice(i, 1); continue; }
      if (s.cd <= 0 && M.dist(p.x, p.y, s.x, s.y) < s.r + 14) {
        s.cd = 1.2;
        this.damage(8, s.x, s.y);
      }
    }

    // ambient music pulse quickens with pressure
    this.musicT -= dt;
    if (this.musicT <= 0) {
      this.musicT = M.clamp(1.1 - this.hazardSpeed * 0.18, 0.4, 1.2);
      GF.Sfx.beep({ freq: 110 + this.nodesActivated * 30, dur: 0.22, type: 'sine', vol: 0.07 });
    }
  },

  draw(ctx) {
    if (!this.bgGrad) {
      const g = ctx.createLinearGradient(0, 0, 0, H);
      g.addColorStop(0, '#08141c');
      g.addColorStop(0.55, '#0a1e26');
      g.addColorStop(1, '#060d14');
      this.bgGrad = g;
    }
    ctx.fillStyle = this.bgGrad;
    ctx.fillRect(0, 0, W, H);
    const t = game.time;

    // botanical circuit veins (dim)
    ctx.strokeStyle = 'rgba(63,242,200,0.07)';
    for (const v of this.veins) {
      ctx.lineWidth = v.w;
      ctx.beginPath(); ctx.moveTo(v.x1, v.y1); ctx.lineTo(v.x2, v.y2); ctx.stroke();
    }
    // vine chain (lit progress)
    for (const c of this.chain) {
      if (c.lit <= 0) continue;
      ctx.strokeStyle = 'rgba(63,242,200,' + (0.25 + 0.55 * c.lit) + ')';
      ctx.lineWidth = 3;
      ctx.shadowColor = C.teal; ctx.shadowBlur = 12;
      ctx.beginPath();
      ctx.moveTo(c.x1, c.y1);
      ctx.lineTo(M.lerp(c.x1, c.x2, c.lit), M.lerp(c.y1, c.y2, c.lit));
      ctx.stroke();
      ctx.shadowBlur = 0;
    }
    // rising plankton motes
    ctx.fillStyle = 'rgba(63,242,200,0.28)';
    for (const m of this.motes) {
      const my = ((m.y - t * m.s) % (H + 40) + H + 40) % (H + 40) - 20;
      ctx.globalAlpha = 0.15 + 0.15 * Math.sin(t * 2 + m.ph);
      ctx.beginPath(); ctx.arc(m.x + Math.sin(t * 0.7 + m.ph) * 12, my, m.r, 0, M.TAU); ctx.fill();
    }
    ctx.globalAlpha = 1;

    // nodes
    for (let i = 0; i < 3; i++) {
      const n = NODES[i];
      const glow = n.active ? 1 : 0.35 + 0.2 * Math.sin(t * 3 + i);
      ctx.strokeStyle = n.active ? C.gold : C.teal;
      ctx.globalAlpha = glow;
      ctx.lineWidth = n.active ? 4 : 2;
      ctx.shadowColor = n.active ? C.gold : C.teal;
      ctx.shadowBlur = n.active ? 26 : 12;
      ctx.beginPath(); ctx.arc(n.x, n.y, n.active ? 26 : 20, 0, M.TAU); ctx.stroke();
      ctx.shadowBlur = 0;
      // activation radius ring (faint)
      ctx.globalAlpha = n.active ? 0.05 : 0.12;
      ctx.setLineDash([6, 10]);
      ctx.beginPath(); ctx.arc(n.x, n.y, NODE_RADIUS, 0, M.TAU); ctx.stroke();
      ctx.setLineDash([]);
      ctx.globalAlpha = 1;
      if (n.pulse > 0) {
        ctx.strokeStyle = C.gold;
        ctx.globalAlpha = n.pulse * 0.8;
        ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(n.x, n.y, 26 + (1 - n.pulse) * 130, 0, M.TAU); ctx.stroke();
      }
      ctx.globalAlpha = 1;
      GF.Draw.text(ctx, n.active ? 'LIT' : 'NODE ' + (i + 1), n.x, n.y + 44, { size: 13, color: n.active ? C.gold : 'rgba(63,242,200,0.7)', weight: '700' });
      // channel hint
      const d = M.dist(this.player.x, this.player.y, n.x, n.y);
      if (!n.active && d < NODE_RADIUS && game.state === 'playing') {
        GF.Draw.text(ctx, 'PRESS SPACE', n.x, n.y - 46, { size: 16, color: C.gold, weight: '800' });
      }
    }

    // storm pulses (expanding hazard rings)
    for (const pu of this.pulses) {
      ctx.strokeStyle = pu.hit ? 'rgba(255,217,119,0.25)' : 'rgba(255,180,110,0.75)';
      ctx.lineWidth = 3;
      ctx.beginPath(); ctx.arc(pu.x, pu.y, pu.r, 0, M.TAU); ctx.stroke();
      ctx.strokeStyle = 'rgba(255,180,110,0.18)';
      ctx.beginPath(); ctx.arc(pu.x, pu.y, Math.max(1, pu.r - 10), 0, M.TAU); ctx.stroke();
    }
    // spores
    for (const s of this.spores) {
      ctx.fillStyle = '#ffb46b';
      ctx.shadowColor = '#ff9a4b'; ctx.shadowBlur = 10;
      ctx.beginPath(); ctx.arc(s.x, s.y, s.r + Math.sin(s.ph) * 1.5, 0, M.TAU); ctx.fill();
      ctx.shadowBlur = 0;
    }

    // player trail ribbon
    ctx.strokeStyle = 'rgba(63,242,200,0.5)';
    ctx.lineWidth = 5;
    ctx.lineCap = 'round';
    ctx.beginPath();
    let started = false;
    for (let i = 0; i < this.trail.length; i += 2) {
      const idx = (this.trailIdx + 2 + i) % this.trail.length;
      if (!started) { ctx.moveTo(this.trail[idx], this.trail[idx + 1]); started = true; }
      else ctx.lineTo(this.trail[idx], this.trail[idx + 1]);
    }
    ctx.stroke();
    // player teardrop of light
    const p = this.player;
    const ang = Math.atan2(p.vy, p.vx);
    ctx.shadowColor = C.teal; ctx.shadowBlur = 24;
    ctx.fillStyle = '#eafff8';
    ctx.beginPath();
    ctx.ellipse(p.x, p.y, 16, 11, ang, 0, M.TAU);
    ctx.fill();
    ctx.shadowBlur = 0;
    ctx.strokeStyle = C.teal; ctx.lineWidth = 2.5;
    ctx.beginPath(); ctx.arc(p.x, p.y, 20, 0, M.TAU); ctx.stroke();

    // pointer attraction shimmer (cosmetic)
    const pt = game.input.pointer;
    if (pt.x || pt.y) {
      ctx.strokeStyle = 'rgba(63,242,200,0.12)';
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(pt.x, pt.y); ctx.stroke();
    }

    GF.Draw.vignette(ctx, W, H, 0.42);

    // ---- HUD: three distinct edge regions (MH-06) ----
    // Region 1: node progress, top-left
    GF.Draw.roundRect(ctx, 16, 14, 218, 46, 10, 'rgba(6,13,20,0.72)');
    GF.Draw.text(ctx, 'SIGNAL NODES', 28, 30, { size: 12, color: 'rgba(63,242,200,0.85)', align: 'left', weight: '700' });
    for (let i = 0; i < 3; i++) {
      const on = i < this.nodesActivated;
      ctx.fillStyle = on ? C.gold : 'rgba(63,242,200,0.22)';
      ctx.beginPath();
      const cx = 150 + i * 28, cy = 37;
      ctx.moveTo(cx, cy - 9); ctx.lineTo(cx + 9, cy); ctx.lineTo(cx, cy + 9); ctx.lineTo(cx - 9, cy);
      ctx.closePath(); ctx.fill();
    }
    // Region 2: score, top-right (below engine BEST line)
    GF.Draw.roundRect(ctx, W - 176, 48, 160, 38, 10, 'rgba(6,13,20,0.72)');
    GF.Draw.text(ctx, 'SCORE ' + game.score, W - 24, 67, { size: 20, color: C.gold, align: 'right', weight: '800' });
    // Region 3: stability bar, bottom-left
    const bw = 240, bx = 20, by = H - 44;
    GF.Draw.roundRect(ctx, bx - 4, by - 20, bw + 8, 44, 10, 'rgba(6,13,20,0.72)');
    GF.Draw.text(ctx, 'STABILITY', bx, by - 6, { size: 12, color: 'rgba(63,242,200,0.85)', align: 'left', weight: '700' });
    const frac = M.clamp(this.stability / 100, 0, 1);
    ctx.fillStyle = 'rgba(255,255,255,0.12)';
    ctx.fillRect(bx, by + 4, bw, 12);
    ctx.fillStyle = frac > 0.25 ? C.teal : '#ff8a5c';
    ctx.fillRect(bx, by + 4, bw * frac, 12);
    ctx.strokeStyle = 'rgba(63,242,200,0.5)'; ctx.lineWidth = 1;
    ctx.strokeRect(bx, by + 4, bw, 12);
    // hazard multiplier readout, bottom-right
    GF.Draw.text(ctx, 'PRESSURE x' + this.hazardSpeed.toFixed(2), W - 24, H - 26, { size: 15, color: '#ffb46b', align: 'right', weight: '700' });
  }
};

game.add('play', play);
game.titleScreen({ subtitle: 'Arrow / WASD to drift - SPACE to channel nodes - Enter to begin' });
})();
